package plates.core.timing

/**
 * [H15] A value moving from [from] to [to] over [ms] from [at], eased by [curve]: the one shape every canvas-level
 * motion takes (the livery fade, the box resize). Read at a frame time; it holds no clock.
 */
class Tween<T>(
    val from: T,
    val to: T,
    val at: Double,
    val ms: Double,
    private val lerp: (T, T, Double) -> T,
    private val curve: PlateCurve = PlateCurves.easeInOut,
) {
    fun running(now: Double) = ms > 0 && now - at < ms

    fun valueAt(now: Double): T = if (!running(now)) to else lerp(from, to, curve.transform(maxOf(0.0, (now - at) / ms)))

    /** A tween from wherever this one is at [now] to [to]. */
    fun retarget(to: T, now: Double, ms: Double) = Tween(valueAt(now), to, now, ms, lerp, curve)

    /** The same motion, landing on [to]. */
    fun follow(to: T) = Tween(from, to, at, ms, lerp, curve)

    companion object {
        fun <T> settled(value: T, lerp: (T, T, Double) -> T) = Tween(value, value, 0.0, 0.0, lerp)
    }
}

typealias Size = Pair<Double, Double>

fun lerpSize(a: Size, b: Size, t: Double): Size = (a.first + (b.first - a.first) * t) to (a.second + (b.second - a.second) * t)
